#!/usr/bin/env python3
"""
install_anchoring.py  --  one-command installer for the OPTIONAL Polygon Amoy audit anchoring.

Run from the ROOT of the Freight-sih repo:

    python install_anchoring.py            # install
    python install_anchoring.py --force    # overwrite the 5 new files if they already exist

What it does (safe to run twice):
  1. Creates 5 new files (service, API router, React component, tests, docs).
  2. Adds 2 lines to backend/app/main.py and 2 lines to frontend/src/main.tsx.
  3. Appends the web3 dependency, placeholder settings and a README section.
It does NOT touch audit.py, database/decisions.py, api/audit.py or any ML/forecast code.

SCOPE: anchoring covers ONLY the hash-chained decision_events, NOT the legacy AuditLogRecord table.
"""
import base64, re, sys
from pathlib import Path

FORCE = "--force" in sys.argv
ROOT = Path.cwd()

NEW_FILES = {
    'backend/app/services/anchoring.py': "",
    'backend/app/api/anchoring.py': "",
    'frontend/src/components/AnchorStatus.tsx': "",
    'tests/test_anchoring.py': "",
    'docs/AUDIT_ANCHORING.md': ""
}

README_SECTION = '\n\n---\n\n## Optional: External Blockchain Anchoring (Polygon Amoy testnet)\n\nMakes the local audit hash chain **externally verifiable**: a Merkle root of new audit events is written to the Polygon Amoy testnet, and the transaction hash is stored locally and shown in the CVC Governance tab (with a PolygonScan link and an **Anchor now** button).\n\n> **Scope:** anchoring covers **only the hash-chained `decision_events`** (Pillar 3 decision timeline). It does **not** cover the legacy `AuditLogRecord` table (the "Immutable Audit Trail" table served by `/audit/logs`), which is not hash-chained and is not anchored.\n\n**Why it is optional:** the platform is designed to run fully offline. This is the only feature that needs internet, and nothing else depends on it. With no key, no `web3`, or no connection, everything else works unchanged and the UI shows "Not anchored / offline".\n\n**Quick start**\n\n1. `pip install -r backend/requirements.txt`\n2. Create a throwaway wallet: `python -c "from eth_account import Account; a=Account.create(); print(a.address); print(a.key.hex())"`\n3. Get free test POL for that address at https://faucet.polygon.technology/ (select *Polygon Amoy*). The faucet is rate-limited, so do this a day before a demo.\n4. Put `AMOY_PRIVATE_KEY=0x...` in `.env` (git-ignored). Optional: `AMOY_RPC_URL`, `ANCHOR_INTERVAL_MINUTES` (0 = manual button only).\n5. Open **CVC Governance** and click **Anchor now**.\n\nEndpoints: `GET /audit/anchor-status`, `POST /audit/anchor`, `GET /audit/anchor/{id}/verify`. Full details and the demo script: [`docs/AUDIT_ANCHORING.md`](docs/AUDIT_ANCHORING.md).\n'
ENV_BLOCK = '\n# --- OPTIONAL: external blockchain anchoring (Polygon Amoy TESTNET). Leave empty to keep it disabled. ---\n# Use a THROWAWAY test wallet only. Never commit a real key. Never put real funds in it.\nAMOY_PRIVATE_KEY=\nAMOY_RPC_URL=https://rpc-amoy.polygon.technology\n# 0 = manual "Anchor now" button only. e.g. 30 = also anchor automatically every 30 minutes.\nANCHOR_INTERVAL_MINUTES=0\n'
REQ_BLOCK = '\n# Optional: external audit anchoring on Polygon Amoy testnet (needs internet + web3). See docs/AUDIT_ANCHORING.md\nweb3>=7.0,<9\n'

def ok(m):   print("  [ok]   " + m)
def skip(m): print("  [skip] " + m)
def warn(m): print("  [MANUAL] " + m)

def read(p):  return p.read_bytes().decode("utf-8", "ignore")
def write(p, s): p.write_bytes(s.encode("utf-8"))

def nl(text, s):
    """match the file's own newline style (Windows CRLF vs Unix LF)"""
    return s.replace("\n", "\r\n") if "\r\n" in text else s

def append_once(path, block, marker):
    p = ROOT / path
    if not p.exists():
        skip(path + " (not found)"); return
    t = read(p)
    if marker in t:
        skip(path + " (already has it)"); return
    if t and not t.endswith("\n"): t += "\n"
    write(p, t + nl(t, block)); ok("updated " + path)

def main():
    if not (ROOT / "backend/app/main.py").exists() or not (ROOT / "frontend/src/main.tsx").exists():
        sys.exit("ERROR: run this from the root of the Freight-sih repo (backend/ and frontend/ must be visible here).")

    print("1) New files")
    for rel, b64 in NEW_FILES.items():
        p = ROOT / rel
        if p.exists() and not FORCE:
            skip(rel + " (exists; use --force to overwrite)"); continue
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_bytes(base64.b64decode(b64)); ok("created " + rel)

    print("2) backend/app/main.py")
    p = ROOT / "backend/app/main.py"; t = read(p)
    if "anchoring_router" in t:
        skip("already wired")
    else:
        a = "from backend.app.api.audit import router as audit_router\n"
        b = "app.include_router(audit_router)\n"
        a, b = nl(t, a), nl(t, b)
        if a in t and b in t:
            t = t.replace(a, a + nl(t, "from backend.app.api.anchoring import router as anchoring_router  # optional, testnet anchoring\n"), 1)
            t = t.replace(b, b + nl(t, "app.include_router(anchoring_router)\n"), 1)
            write(p, t); ok("router registered")
        else:
            warn("add these 2 lines to backend/app/main.py yourself:\n"
                 "        from backend.app.api.anchoring import router as anchoring_router\n"
                 "        app.include_router(anchoring_router)")

    print("3) frontend/src/main.tsx")
    p = ROOT / "frontend/src/main.tsx"; t = read(p)
    if "AnchorStatus" in t:
        skip("already wired")
    else:
        imp = 'import { AuditTimeline } from "./components/AuditTimeline";'
        done_imp = imp in t
        if done_imp:
            t = t.replace(imp, imp + nl(t, '\nimport { AnchorStatus } from "./components/AnchorStatus";'), 1)
        m = re.search(r"<AuditTimeline />\s*</>\s*\)\}[ \t]*\r?\n", t)
        if done_imp and m:
            ins = nl(t, "\n              {/* OPTIONAL testnet anchoring of the decision_events chain (needs internet) */}\n              <AnchorStatus />\n")
            t = t[:m.end()] + ins + t[m.end():]
            write(p, t); ok("<AnchorStatus /> added to the CVC Governance tab")
        else:
            warn("add manually in frontend/src/main.tsx:\n"
                 '        1) at the top:  import { AnchorStatus } from "./components/AnchorStatus";\n'
                 "        2) in the governance tab, right after the block that contains <AuditTimeline />\n"
                 "           and just before </section>:   <AnchorStatus />")

    print("4) Config + docs")
    append_once("backend/requirements.txt", REQ_BLOCK, "web3")
    append_once(".env.example", ENV_BLOCK, "AMOY_PRIVATE_KEY")
    append_once("backend/.env.example", ENV_BLOCK, "AMOY_PRIVATE_KEY")
    append_once("README.md", README_SECTION, "External Blockchain Anchoring")

    print("""
DONE. Next steps:
  pip install -r backend/requirements.txt
  pytest tests/test_anchoring.py tests/test_audit.py -q
  python -c "from eth_account import Account; a=Account.create(); print(a.address); print(a.key.hex())"
  -> fund that address at https://faucet.polygon.technology/ (Polygon Amoy)
  -> put AMOY_PRIVATE_KEY=0x... in .env
  uvicorn backend.app.main:app --host 127.0.0.1 --port 8000
  cd frontend && npm install && npm run dev      (open CVC Governance tab, click "Anchor now")
""")

main()
